sed -i 's/class GlobalExceptionHandler(/class GlobalExceptionHandler(\n  private val context: Context,\n  private val activity: Class<*>,\n  private val defaultHandler: Thread.UncaughtExceptionHandler? = Thread.getDefaultUncaughtExceptionHandler()\n) : Thread.UncaughtExceptionHandler {\n  private val appLaunchTime = System.currentTimeMillis()\n\n  override fun uncaughtException(t: Thread, e: Throwable) {\n    if (System.currentTimeMillis() - appLaunchTime < 3000) {\n      defaultHandler?.uncaughtException(t, e)\n      return\n    }\n    val intent = Intent(context, activity)\n    intent.addFlags(Intent.FLAG_ACTIVITY_NEW_TASK)\n    intent.addFlags(Intent.FLAG_ACTIVITY_CLEAR_TASK)\n    intent.putExtra("exception", e.stackTraceToString())\n    context.startActivity(intent)\n    exitProcess(0)\n  }\n}\n\/\/ /' app/src/main/kotlin/xyz/mpv/rex/presentation/crash/GlobalExceptionHandler.kt
